def test_made_masks_are_autoregressive():
    d, h = 6, 64
    m1, m2, m3 = made_masks(d, h)
    conn = (m3 @ m2 @ m1) > 0          # output unit -> input dependence
    for i in range(d):                 # mu_i and s_i may depend only on inputs < i
        assert not conn[i, i:].any() and not conn[d + i, i:].any()
    assert conn[d - 1, : d - 1].all()  # last variable sees all earlier ones


def test_log_prob_normalises_in_one_dimension():
    rng = np.random.default_rng(0)
    d, k, h = 1, 2, 8
    layers = [{"W1": rng.normal(0, 0.5, (h, d)), "V1": rng.normal(0, 0.5, (h, k)), "b1": rng.normal(0, 0.1, h),
               "W2": rng.normal(0, 0.5, (h, h)), "b2": rng.normal(0, 0.1, h), "W3": rng.normal(0, 0.3, (2 * d, h)),
               "b3": rng.normal(0, 0.1, 2 * d)} for _ in range(3)]
    grid = np.linspace(-12, 12, 20001)[:, None]
    c = np.repeat(rng.standard_normal((1, k)), grid.shape[0], 0)
    p = np.exp(log_prob(grid, c, layers, h))
    assert abs(np.trapezoid(p, grid[:, 0]) - 1.0) < 1e-4


def test_sbc_detects_calibrated_and_overconfident_posteriors():
    rng = np.random.default_rng(1)
    n, s = 3000, 199
    truth = rng.standard_normal((n, 1))
    obs = truth + rng.standard_normal((n, 1))                   # posterior N(obs/2, 1/2)
    good = obs[:, None, :] / 2 + np.sqrt(0.5) * rng.standard_normal((n, s, 1))
    bad = obs[:, None, :] / 2 + 0.3 * rng.standard_normal((n, s, 1))
    ug = rank_uniformity(sbc_ranks(good, truth), s)
    ub = rank_uniformity(sbc_ranks(bad, truth), s)
    assert ug["chi2"][0] < 30 and abs(ug["coverage68"][0] - 0.68) < 0.03
    assert ub["chi2"][0] > 200 and ub["coverage68"][0] < 0.5


def test_device_log_density_recomputed_in_float64():
    assert ATTESTATION is not None, "run scripts/run_npe.py --stages attest"
    a = ATTESTATION
    flat = np.frombuffer(base64.b64decode(a["weights_float32_b64"]), dtype=np.float32).astype(np.float64)
    d, k, h = a["d"], a["k"], a["hidden"]
    shapes = {"W1": (h, d), "V1": (h, k), "b1": (h,), "W2": (h, h), "b2": (h,), "W3": (2 * d, h), "b3": (2 * d,)}
    layers, pos = [], 0
    for _ in range(a["layers"]):
        layer = {}
        for name, shp in shapes.items():
            size = int(np.prod(shp))
            layer[name] = flat[pos:pos + size].reshape(shp)
            pos += size
        layers.append(layer)
    assert pos == flat.size
    lp = log_prob(np.array(a["x"]), np.array(a["c"]), layers, h)
    dev = np.array(a["log_prob_device"])
    # float32 on the device vs float64 here: relative agreement at float32 precision
    assert np.all(np.abs(lp - dev) <= a["rel_tolerance"] * np.maximum(1.0, np.abs(dev)))


def test_importance_reweighting_matches_direct_sampling():
    # Joint samples with x2 ~ U(-5, 5); reweighting to x2 ~ N(0, 1) must reproduce the
    # conditional-mixture quantiles of x1 = x2 + noise, i.e. x1 ~ N(0, sqrt(1 + 0.3^2)).
    rng = np.random.default_rng(4)
    x2 = rng.uniform(-5, 5, 400000)
    x1 = x2 + 0.3 * rng.standard_normal(x2.size)
    q = weighted_q(x1, np.exp(-0.5 * x2**2))
    sd = np.sqrt(1 + 0.09)
    assert abs(q["median"]) < 0.02
    assert abs(q["hi68"] - q["lo68"] - 2 * 0.9945 * sd) < 0.03
    assert 0.32 * x2.size < q["ess"] < 0.39 * x2.size     # expected fraction (sqrt(2 pi)/10)^2 / (sqrt(pi)/10) = 0.355


def test_interval_scale_recovers_known_miscalibration():
    # Gaussian truths around the median; intervals built with sd 0.8 of the true spread are
    # overconfident and need k = 1/0.8; exact ones need k = 1.
    rng = np.random.default_rng(3)
    n = 200000
    truth = rng.standard_normal(n)
    med = np.zeros(n)
    for width, k_true in ((0.8, 1.25), (1.0, 1.0)):
        h68, h95 = 0.99446 * width, 1.95996 * width
        k = interval_scale(med, med - h68, med + h68, med - h95, med + h95, truth)
        assert abs(k["k68"] - k_true) < 0.02 and abs(k["k95"] - k_true) < 0.02, (width, k)
